import {scaleStops,scalePosition,scaleAt} from './studio-science.js';
import {studioArt} from './studio-art.js';
export function createScaleJourney(root,api){
 let position=0,target=0,index=-1,active=false,frame=0,last=0;const visited=new Set(),reduce=matchMedia('(prefers-reduced-motion: reduce)');
 root.innerHTML=`<div class="studio-section-head"><div><span class="studio-kicker">01 / VŨ TRỤ SỐNG</span><h2>Một chiếc lá. Cả một thế giới.</h2><p>Cuộn trong khung quan sát để đi từ khu rừng đến nguyên tử. Kéo thang kích thước hoặc chọn một điểm dừng.</p></div><span class="studio-label">THANG LOGARITHM</span></div><div class="scale-layout"><div class="scale-world" tabindex="0" role="region" aria-label="Hành trình phóng đại. Dùng phím mũi tên lên xuống hoặc thang kích thước bên dưới."><div class="scale-scenes" aria-hidden="true">${scaleStops.map(s=>`<div class="scale-scene scale-scene-${s.id}" data-scale-scene="${s.id}">${s.id==='forest'?'<img src="assets/forest.jpg" alt="" loading="lazy">':s.id==='cell'||s.id==='dna'?`<img src="assets/${s.id}-thumbnail.png" alt="" loading="lazy">`:studioArt(s.id,s.name)}</div>`).join('')}</div><div class="scale-world-hud"><span>VNS / LIVING SCALE</span><span id="scale-visited">0 / 7 điểm dừng</span></div><div class="scale-reticle" aria-hidden="true"></div><div class="scale-scene-caption"><span id="scale-tag"></span><strong id="scale-name"></strong><span id="scale-size"></span></div><span class="scale-wheel-hint">Cuộn để đến gần · Chạm các mốc để khám phá</span></div><aside class="scale-details"><span class="studio-kicker" id="scale-stage-number"></span><h3 id="scale-title"></h3><p id="scale-description"></p><details class="studio-prompt"><summary>Một câu hỏi để nhìn kỹ hơn</summary><p id="scale-question"></p></details><div class="studio-button-row"><button type="button" id="scale-prev" class="studio-button secondary">← Xa hơn</button><button type="button" id="scale-next" class="studio-button">Gần hơn →</button></div><button type="button" id="scale-save" class="studio-text-button">Lưu điểm nhìn vào sổ tay ↗</button><p class="studio-fineprint">Kích thước là mốc minh họa gần đúng. Sơ đồ và chuyển cảnh giúp so sánh các thang đo, không phải ảnh quay xuyên vào cùng một mẫu vật.</p></aside></div><div class="scale-controller"><label for="living-scale">Thang quan sát <output id="scale-readout">20 m</output></label><input id="living-scale" type="range" min="0" max="1000" value="0" step="1" aria-label="Phóng đại từ khu rừng đến nguyên tử"><div class="scale-stops">${scaleStops.map((s,i)=>`<button type="button" data-scale-stop="${i}"><span>${String(i+1).padStart(2,'0')}</span>${s.name}<small>${s.label}</small></button>`).join('')}</div></div><div class="studio-insight"><span>ĐIỀU GÌ NỐI CÁC THANG ĐO?</span><p>Nguyên tử tạo phân tử; DNA là một phân tử mang thông tin. Tế bào tổ chức nhiều phân tử để duy trì sự sống. Không phải cứ nhỏ hơn là “sống” hơn.</p><a href="#/microscope">Tự tìm nét dưới kính hiển vi →</a></div>`;
 const range=root.querySelector('#living-scale'),world=root.querySelector('.scale-world'),scenes=[...root.querySelectorAll('.scale-scene')];
 function update(){const current=scaleAt(position),i=current.index;if(i!==index){index=i;visited.add(i);const s=scaleStops[i];root.querySelector('#scale-stage-number').textContent=`ĐIỂM NHÌN ${String(i+1).padStart(2,'0')} / 07`;for(const [id,text] of [['scale-title',s.title],['scale-description',s.text],['scale-question',s.question],['scale-tag',s.tag],['scale-name',s.name],['scale-size',s.label],['scale-readout',s.label]])root.querySelector('#'+id).textContent=text;root.querySelector('#scale-visited').textContent=`${visited.size} / 7 điểm dừng`;root.querySelector('#scale-prev').disabled=i===0;root.querySelector('#scale-next').disabled=i===6;root.querySelectorAll('[data-scale-stop]').forEach((b,j)=>{b.setAttribute('aria-pressed',String(i===j));b.classList.toggle('selected',i===j)});if(visited.size===7)api.award('scale','Đã đi qua bảy thang kích thước')}
  scenes.forEach((el,j)=>{const distance=(position-scalePosition(j))/95,opacity=Math.max(0,1-Math.abs(distance)/1.4);el.style.opacity=String(j===i?Math.max(.3,opacity):opacity*.45);el.style.transform=`scale(${Math.max(.55,Math.min(1.8,1+distance*.24))})`;el.style.zIndex=j===i?'2':'1'});range.value=String(Math.round(position));
 }
 function tick(now){const elapsed=Math.min(64,now-last||16);last=now;position+= (target-position)*(1-Math.exp(-elapsed/115));if(Math.abs(target-position)<.2)position=target;update();if(active&&position!==target)frame=requestAnimationFrame(tick);else frame=0}
 function move(value){target=Math.max(0,Math.min(1000,value));if(reduce.matches){position=target;update()}else if(active&&!frame)frame=requestAnimationFrame(tick)}
 function go(i){move(scalePosition(Math.max(0,Math.min(6,i))))}
 range.addEventListener('input',()=>move(Number(range.value)));root.querySelectorAll('[data-scale-stop]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.scaleStop))));
 root.querySelector('#scale-prev').addEventListener('click',()=>go(index-1));root.querySelector('#scale-next').addEventListener('click',()=>go(index+1));
 world.addEventListener('wheel',e=>{if(!active||e.ctrlKey||e.metaKey)return;const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?world.clientHeight:1);if((target<=0&&delta<0)||(target>=1000&&delta>0))return;e.preventDefault();move(target+Math.max(-90,Math.min(90,delta*.22)))},{passive:false});
 world.addEventListener('keydown',e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home')go(0);else if(e.key==='End')go(6);else go(index+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1))}});
 root.querySelector('#scale-save').addEventListener('click',()=>{const s=scaleStops[index];api.saveNote(`Một điểm nhìn: ${s.name}`,`Thang kích thước: ${s.label}\n${s.text}\n\nCâu hỏi tiếp theo: ${s.question}`)});update();
 return {setActive(value){active=value;if(!active){cancelAnimationFrame(frame);frame=0;position=target;update()}else if(position!==target)frame=requestAnimationFrame(tick)}};
}
